const copy = {
  zh: {title:'让笔记有一点纸上的温度。',intro:'同一份内容，三种材质语言。先比较静态画面，再决定互动。',kitLabel:'建议的最小素材语言',kitTitle:'以 B 为基础，文具作为可选项。',kitBody:'一张网格纸、一种批注色、三类手绘笔迹。先建立一致性，再增加个人材料。',paper:'暖白细网格 / 一种纸张',marks:'圈线 · 箭头 · 下划线',color:'灰黑正文＋陶土色批注',optional:'胶带与铅笔 / 可选',footer:'静态设计预览 · 尚未应用到正式 Notes',back:'返回笔记页 ↗',note:'当 Agent 开始工作，UI 开始转化',nodes:['人','Agent','界面状态'],annotation:'判断留给人',variants:[['纯网格纸','最克制的版本。依靠纸张、页码与信息层级，检验基础质感。'],['网格纸＋手绘批注','建议方向。用一处圈线和短批注表达设计观点，保留阅读的秩序。'],['网格纸＋桌面拼贴','桌面感更明显。加入半透明胶带与铅笔片段，比较实物层次的表达。']]},
  en: {title:'A little warmth, on paper.',intro:'One note, three material directions. Compare the stills before adding interaction.',kitLabel:'PROPOSED MINIMAL KIT',kitTitle:'Start with B. Keep stationery optional.',kitBody:'One grid paper, one annotation color, three kinds of drawn marks. Establish consistency before adding personal materials.',paper:'Warm grid / one paper',marks:'Circles · arrows · underlines',color:'Charcoal text + clay annotations',optional:'Tape & pencil / optional',footer:'Static design study · not applied to Notes',back:'Back to Notes ↗',note:'When agents start working, UI starts transforming',nodes:['Human','Agent','UI state'],annotation:'Keep human judgment',variants:[['Grid paper','The quietest version. Paper, page numbering and hierarchy establish the base material.'],['Paper + drawn annotation','Recommended. One circle and a short margin note express a point of view while keeping a clear reading order.'],['Paper + desk collage','More of a desktop feel. Translucent tape and a pencil fragment explore a more physical composition.']]}
};
let language = localStorage.getItem('portfolio-language') === 'en' ? 'en' : 'zh';
let theme = localStorage.getItem('portfolio-theme') === 'dark' ? 'dark' : 'light';
const clip = '<span class="study-tape" aria-hidden="true"></span><span class="study-pencil" aria-hidden="true"></span>';
function diagram(marked,c){return `<svg class="diagram" viewBox="0 0 320 166" aria-hidden="true"><rect class="diagram-box" x="5" y="58" width="76" height="44" rx="5"/><rect class="diagram-box" x="121" y="58" width="76" height="44" rx="5"/><rect class="diagram-box" x="237" y="58" width="78" height="44" rx="5"/><text x="43" y="85" text-anchor="middle">${c.nodes[0]}</text><text x="159" y="85" text-anchor="middle">${c.nodes[1]}</text><text x="276" y="85" text-anchor="middle">${c.nodes[2]}</text><path class="flow" d="M85 80h29m-5-4 5 4-5 4M201 80h29m-5-4 5 4-5 4"/>${marked?`<path class="sketch" d="M28 51C-4 55-5 110 40 112c52 3 62-59 14-64-11-2-20 0-27 5M37 44C40 35 60 29 84 30m-6-4 6 4-5 5"/><text class="annotation" x="92" y="33">${c.annotation}</text><path class="sketch" d="M94 39q51 4 112-1"/>`:''}</svg>`;}
function render(){const c=copy[language];document.documentElement.lang=language;document.body.dataset.language=language;document.body.dataset.theme=theme;document.querySelectorAll('[data-copy]').forEach(el=>el.textContent=c[el.dataset.copy]);document.querySelector('#language').textContent=language==='zh'?'EN':'中';document.querySelector('#comparisons').innerHTML=c.variants.map(([title,caption],i)=>`<article><div class="variant-heading"><h2>${title}</h2><span class="variant-letter">0${i+1} / ${'ABC'[i]}</span></div><div class="paper-card ${i===2?'with-clip':''}">${i===2?clip:''}<div class="paper-head"><span class="page-number">01</span><span class="paper-topic">AGENTIC UX</span></div>${diagram(i===1,c)}<h3>${c.note}</h3><div class="paper-tags"><span>AGENTIC UX</span><span>TRUST</span><span>VISIBILITY</span></div></div><p class="variant-caption">${caption}</p></article>`).join('');}
document.querySelector('#language').addEventListener('click',()=>{language=language==='zh'?'en':'zh';render();});
document.querySelector('#theme').addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';render();});
render();
